INSERT INTO public.assessment_questions (framework, section_id, section_name, subsection, question_number, question, why_matters, regulatory_ref, risk, evidence_req, remediation, uid) VALUES
('popia', 4, 'Data Subject Rights', 'Access Requests', 1, 'Does the organisation have a documented procedure for handling data subject access requests?', 'Section 23 provides data subjects with the right to access their personal information. Organisations must have procedures to handle these requests.', 'POPIA Section 23 data subject rights; ISO 27701 cl.7.3.2 access requests', 'Critical', 'Access request handling procedures; response time tracking; verification procedures; request forms; records of requests and responses.', 'Implement comprehensive access request handling procedure. Track response times to ensure compliance with legal deadlines. Document all requests and responses.', 'P4_DSR_1'),
('popia', 4, 'Data Subject Rights', 'Access Requests', 2, 'Can data subjects access their personal information within the legal timeframes?', 'Section 23 requires organisations to provide access without unreasonable delay and within a reasonable time.', 'POPIA Section 23 access timelines; ISO 27701 cl.7.3.2 access requests', 'High', 'Response time tracking; compliance monitoring; user feedback on response times; process improvement records.', 'Monitor response times to ensure legal compliance. Implement process improvements where needed. Track and report on performance.', 'P4_DSR_2'),
('popia', 4, 'Data Subject Rights', 'Correction Requests', 3, 'Does the organisation have procedures for data subject correction requests?', 'Section 24 provides data subjects with the right to request correction of inaccurate personal information.', 'POPIA Section 24 correction rights; ISO 27701 cl.7.3.2 access requests', 'High', 'Correction request procedures; update procedures; verification processes; records of correction requests.', 'Implement correction request handling procedure. Establish verification processes for correction requests. Document all correction activities.', 'P4_DSR_3'),
('popia', 4, 'Data Subject Rights', 'Deletion Requests', 4, 'Does the organisation have procedures for data subject deletion requests?', 'Section 24 provides data subjects with the right to request deletion of their personal information, subject to legal exceptions.', 'POPIA Section 24 deletion rights; ISO 27701 cl.7.3.2 access requests; legal retention requirements', 'Critical', 'Deletion request procedures; legal exception documentation; retention schedule review; data deletion verification.', 'Implement deletion request handling procedure. Document legal exceptions to deletion. Review retention schedules to ensure compliance.', 'P4_DSR_4'),
('popia', 4, 'Data Subject Rights', 'Deletion Requests', 5, 'Does the organisation verify the identity of data subjects before fulfilling deletion requests?', 'Section 24 allows organisations to verify the identity of data subjects before fulfilling deletion requests to prevent unauthorised deletion.', 'POPIA Section 24 identity verification; ISO 27701 cl.7.3.2 access requests', 'Critical', 'Identity verification procedures; verification records; handling of anonymous requests; privacy policy disclosure of verification.', 'Implement identity verification procedures for deletion requests. Document verification process in privacy policy.', 'P4_DSR_5'),
('popia', 4, 'Data Subject Rights', 'Objection to Processing', 6, 'Does the organisation have procedures for data subject objection to processing requests?', 'Section 24 provides data subjects with the right to object to processing of their personal information.', 'POPIA Section 24 objection rights; ISO 27701 cl.7.3.2 access requests', 'High', 'Objection handling procedures; response procedures; appeal processes; records of objection requests.', 'Implement objection request handling procedure. Provide clear response procedures. Establish appeal mechanisms for disputed objections.', 'P4_DSR_6'),
('popia', 4, 'Data Subject Rights', 'Juristic Person Rights', 7, 'Does the organisation recognise and protect juristic person data subject rights?', 'Unlike GDPR, POPIA protects juristic persons (companies, trusts) as data subjects. Their rights must be recognised and protected.', 'POPIA Section 1(3) juristic persons; POPIA Section 24 rights applicable to juristic persons', 'Medium', 'Juristic person handling procedures; verification procedures for juristic persons; access procedures for organisational data subjects.', 'Adapt procedures to recognise juristic person data subjects. Implement appropriate verification and access procedures for organisational data subjects.', 'P4_DSR_7'),
('popia', 4, 'Data Subject Rights', 'Automated Decision Making', 8, 'Does the organisation conduct data protection impact assessments (DPIAs) for automated decision-making?', 'Section 71 regulates automated decision-making and requires data subjects to be provided with meaningful information about the logic involved.', 'POPIA Section 71 automated decision making; ISO 27701 cl.7.3.3 automated decision making', 'High', 'DPIA documentation for automated systems; transparency documentation; appeal mechanisms for automated decisions; user testing of automated systems.', 'Conduct DPIAs for all automated decision-making systems. Provide meaningful information about logic to data subjects. Implement appeal mechanisms.', 'P4_DSR_8'),
('popia', 4, 'Data Subject Rights', 'Request Fees', 9, 'Does the organisation charge reasonable fees for data subject requests?', 'Section 24 allows organisations to charge reasonable fees for data subject requests, but the fee must not be excessive.', 'POPIA Section 24 request fees; ISO 27701 cl.7.3.2 access requests', 'Medium', 'Fee structure documentation; fee calculation records; fee waiver policies; transparency about fees in privacy policy.', 'Develop fee structure for data subject requests. Document fee calculation methodology. Implement fee waiver policies. Disclose fees in privacy policy.', 'P4_DSR_9'),
('popia', 4, 'Data Subject Rights', 'Request Documentation', 10, 'Are all data subject requests and responses documented?', 'Section 24 requires organisations to keep records of data subject requests and responses.', 'POPIA Section 24 documentation; ISO 27701 cl.7.3.2 access requests', 'Medium', 'Request logging system; response documentation; record retention schedule; audit trail of request handling.', 'Implement request logging system to capture all data subject requests and responses. Maintain records for legal retention period.', 'P4_DSR_10');